<div class="page-heading"><div><span class="eyebrow">Communication du club</span><h1>Boîte de réception</h1><p>Offres, rapports, résultats et messages de la direction.</p></div></div>
<div class="inbox-list"><?php foreach ($messages as $message): ?><article class="inbox-item <?= $message['is_read'] ? 'is-read' : '' ?>"><div class="inbox-item__icon"><?= $message['category'] === 'transfer' ? '⇄' : ($message['category'] === 'board' ? '◇' : '✉') ?></div><div class="inbox-item__content"><div><span class="badge"><?= e($message['category']) ?></span><time><?= format_date($message['created_at'],'d/m/Y H:i') ?></time></div><h2><?= e($message['subject']) ?></h2><p><?= nl2br(e($message['body'])) ?></p><?php if ($message['action_url']): ?><a class="text-link" href="<?= e($message['action_url']) ?>">Ouvrir la page concernée →</a><?php endif; ?></div><?php if (!$message['is_read']): ?><form method="post" action="/saves/<?= (int)$context->saveId() ?>/messages/<?= (int)$message['id'] ?>/read"><input type="hidden" name="_token" value="<?= e(csrf_token()) ?>"><button class="btn btn--ghost btn--sm">Marquer comme lu</button></form><?php endif; ?></article><?php endforeach; ?><?php if (!$messages): ?><div class="empty-state"><h2>Boîte de réception vide</h2></div><?php endif; ?></div>
